*{box-sizing:border-box}body{margin:0;background:#f8f4ed;color:#342e25;font:16px/1.65 Arial,sans-serif}a{color:inherit;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #8b4a28;outline-offset:5px}.shell{max-width:1060px;margin:auto;padding:0 6%}.nav{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:25px 0;border-bottom:1px solid #d8cbb9}.brand{font-size:17px;letter-spacing:1px;font-weight:800;line-height:1.3}.brand span{display:block;font-size:10px;letter-spacing:3px;color:#81644d;margin-top:5px}.nav a{font-size:12px}.hero{display:grid;grid-template-columns:1.4fr 1fr;gap:45px;align-items:center;padding:52px 0 37px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#89532f}h1{font:normal clamp(40px,5vw,61px)/1.1 Georgia,serif;letter-spacing:-1.4px;margin:17px 0 21px}.intro{color:#756854;max-width:490px;font-size:15px}.scene{width:100%;height:auto;max-height:270px}h2{font:normal 29px/1.2 Georgia,serif;letter-spacing:-.5px}.faqs{border-top:1px solid #cdbb9f;margin:10px 0 38px}.faqs details{border-bottom:1px solid #cdbb9f;padding:0;margin:0!important}.faqs summary{cursor:pointer;font-size:16px;font-weight:600;list-style:none;padding:22px 32px 22px 0;position:relative;line-height:1.5}.faqs summary::-webkit-details-marker{display:none}.faqs summary:after{content:'+';position:absolute;right:2px;top:20px;font-size:22px;font-weight:400;color:#8b5939}.faqs details[open] summary:after{content:'−'}.faqs p{max-width:760px;margin:0 36px 23px 0;color:#6d624f;font-size:14px;line-height:1.8}.booking{display:grid;grid-template-columns:1.4fr 1fr;gap:30px;align-items:center;padding:30px;background:#e9dfcf;border:1px solid #ddd0bd}.booking h2{margin:11px 0}.booking p{font-size:13px;color:#6d624f;margin:10px 0}.facts{font-size:11px;letter-spacing:.3px}.action{display:flex;flex-direction:column;align-items:flex-start}.price{font:normal 36px/1.2 Georgia,serif}.price small{display:block;font:11px Arial,sans-serif;letter-spacing:.5px;margin:7px 0 19px}.button{display:inline-flex;align-items:center;justify-content:center;background:#754527;color:#fff;padding:13px 20px;font-size:12px;text-decoration:none;min-height:44px}.note{font-size:10px!important;line-height:1.6}.footer{margin:38px 0 0;padding:23px 0 28px;border-top:1px solid #d8cbb9;display:flex;justify-content:space-between;gap:22px;font-size:10px;color:#756854}.samplebar{padding:8px 6%;background:#e9dfcf;color:#5d4a35;display:flex;justify-content:space-between;gap:15px;font:10px Arial,sans-serif}.samplebar a{font-weight:600}.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}@media(max-width:650px){.shell{padding:0 6%}.hero{grid-template-columns:1fr;gap:10px;padding:32px 0 20px}.hero h1{font-size:43px}.scene{max-height:180px}.nav{padding:21px 0}.nav a{font-size:11px}.brand{font-size:15px}.booking{grid-template-columns:1fr;gap:20px;padding:24px}.faqs summary{font-size:15px}.faqs p{margin-right:8px}.footer{flex-wrap:wrap;margin-top:30px}.samplebar{font-size:9px}.price small{display:inline;font-size:10px;margin-left:10px}.button{margin-top:16px}.action{align-items:flex-start}}
.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}
